const rgbHex=(red:number,green:number,blue:number)=>`#${[red,green,blue].map(value=>Math.max(0,Math.min(255,Math.round(value))).toString(16).padStart(2,"0")).join("")}`;
const colourDistance=(left:[number,number,number],right:[number,number,number])=>Math.sqrt(left.reduce((total,value,index)=>total+(value-right[index])**2,0));
async function dominantLogoColours(source:string){
 return await new Promise<string[]>((resolve,reject)=>{
  const image=new Image();
  image.onload=()=>{
   try{
    const size=96,canvas=document.createElement("canvas");canvas.width=size;canvas.height=size;
    const context=canvas.getContext("2d",{willReadFrequently:true});if(!context)throw new Error("Logo colour analysis is unavailable in this browser.");
    context.clearRect(0,0,size,size);context.drawImage(image,0,0,size,size);
    const pixels=context.getImageData(0,0,size,size).data,counts=new Map<string,{count:number;rgb:[number,number,number]}>();
    for(let index=0;index<pixels.length;index+=16){if(pixels[index+3]<160)continue;const red=pixels[index],green=pixels[index+1],blue=pixels[index+2],maximum=Math.max(red,green,blue),minimum=Math.min(red,green,blue);if(maximum>244&&minimum>238)continue;const quantized:[number,number,number]=[red,green,blue].map(value=>Math.min(255,Math.round(value/24)*24)) as [number,number,number];const key=quantized.join(","),current=counts.get(key);counts.set(key,{count:(current?.count??0)+1,rgb:quantized});}
    const selected:[number,number,number][]=[];
    for(const candidate of [...counts.values()].sort((left,right)=>right.count-left.count)){if(selected.every(existing=>colourDistance(existing,candidate.rgb)>=54))selected.push(candidate.rgb);if(selected.length===8)break;}
    if(!selected.length)throw new Error("No usable logo colours were detected. Try a PNG or WebP logo with a transparent or plain background.");
    resolve(selected.map(colour=>rgbHex(...colour)));
   }catch(error){reject(error)}
  };
  image.onerror=()=>reject(new Error("The logo could not be read for colour analysis. Upload a PNG, JPEG, WebP, or SVG file and try again."));
  image.src=source;
 });
}
