const object = (v:unknown):Record<string,unknown> => v&&typeof v==="object"&&!Array.isArray(v)?v as Record<string,unknown>:{};
const array = (v:unknown):unknown[] => Array.isArray(v)?v:[];
const string = (v:unknown,f="Not generated yet") => typeof v==="string"&&v.trim()?v:f;
const canonicalWebsiteTarget = (value:unknown) => {
 const raw=String(value??"").trim();
 if(!raw)return"";
 try{return new URL(raw,"https://senuke.local").pathname.replace(/\/+$/,"").toLowerCase()||"/"}catch{return raw.replace(/^https?:\/\/[^/]+/i,"").replace(/\/+$/,"").toLowerCase()||"/"}
};
const html = (v:unknown) => String(v??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
const paragraphHtml = (v:unknown) => String(v??"").split(/\n{2,}/).map(paragraph=>paragraph.replace(/\s+/g," ").trim()).filter(Boolean).map(paragraph=>`<p>${html(paragraph)}</p>`).join("");
function canonicalPageContent(value:unknown){
 const content=object(value),components=array(content.components).map(object),hero=components.find(component=>component.componentId==="hero.local_service"),cta=components.find(component=>component.componentId==="conversion.cta"),faq=components.find(component=>component.componentId==="content.faq");
 const sections=components.flatMap((component,componentIndex)=>{
  const props=object(component.props),componentId=String(component.componentId||"");
  if(componentId==="content.rich_text")return[{componentIndex,heading:string(props.heading,"Page content"),headingLevel:"h2",bodyHtml:paragraphHtml(props.body)}];
  if(componentId==="content.link_section"){
   const links=array(props.links).map(object).filter(item=>string(item.label,"")&&string(item.url,""));
   const body=`${paragraphHtml(props.introduction)}<ul>${links.map(item=>`<li><a href="${html(item.url)}">${html(item.label)}</a></li>`).join("")}</ul>${paragraphHtml(props.closingText)}`;
   return[{componentIndex,heading:string(props.heading,"Related information"),headingLevel:"h2",bodyHtml:body}];
  }
  if(["service.grid","service.benefits","trust.proof"].includes(componentId)){
   const items=array(props.items).map(object),body=[props.introduction,...items.flatMap(item=>[item.title,item.description])].filter(Boolean).map(item=>`<p>${html(item)}</p>`).join("");
   return[{componentIndex,heading:string(props.heading,"More information"),headingLevel:"h2",bodyHtml:body}];
  }
  if(componentId==="content.process"){
   const steps=array(props.steps).map(object);
   return[{componentIndex,heading:string(props.heading,"How the process works"),headingLevel:"h2",bodyHtml:`<ol>${steps.map(item=>`<li><strong>${html(item.title)}</strong> ${html(item.description)}</li>`).join("")}</ol>`}];
  }
  return[];
 });
 return{
  components,
  hero:{eyebrow:string(object(hero?.props).eyebrow,""),title:string(object(hero?.props).headline,""),summary:string(object(hero?.props).summary,""),buttonLabel:string(object(hero?.props).primaryCtaLabel,"")},
  cta:{title:string(object(cta?.props).heading,""),body:string(object(cta?.props).body,""),label:string(object(cta?.props).buttonLabel,"")},
  sections,
  faqs:array(object(faq?.props).items).map(object),
 };
}
const isMissingRegisteredPageStructure = (reason:string) => /no registered sections|exactly one hero headline|requires (?:hero\.local_service|content\.rich_text|trust\.proof|conversion\.cta)/i.test(reason);
const isRepairableSchemaBlocker = (reason:string) => /schema must use the approved business identity|approved FAQs but no matching FAQPage schema|requires a Service entity in its approved schema|schema must identify its approved market/i.test(reason);
const isRepairablePageIntentBlocker = (reason:string) => /competes with .+ for the same primary keyword, intent, and location|declare the same indexable intent owner/i.test(reason);
const isRepairableSeoTitleBlocker = (reason:string) => /uses the same SEO title as/i.test(reason);
const isRepairableContentDepthBlocker = (reason:string) => /contains approximately \d+ words.+more useful detail is needed/i.test(reason);
const schemaFindingCodes = new Set(["schema_business_identity_mismatch","missing_faq_schema","missing_service_entity_schema","missing_local_entity_schema"]);
const pageMapFindingCodes = new Set(["duplicate_slug","duplicate_page_intent","duplicate_intent_owner","keyword_map_conflict","location_authority_market_mismatch","missing_location_authority_hub","incomplete_location_authority_cluster"]);
const localEvidenceFindingCodes = new Set(["unverified_local_service_availability","missing_local_uniqueness_evidence","location_authority_cluster_too_small"]);
const claimFindingCodes = new Set(["governance.regulated_or_guaranteed_claim","governance.unsupported_business_claim"]);
const navigationFindingCodes = new Set(["blocked_internal_link","broken_internal_link","internal_link_source_mismatch","internal_self_link","missing_internal_anchor","orphan_indexable_page","missing_cluster_hub_link","missing_breadcrumb_path","noindex_in_primary_navigation","primary_navigation_too_large"]);
