function suggestedFooterMenuItems(pages:Page[]):MenuItem[]{
 const groups=[
  {id:"quick-links",label:"Quick links",match:(page:Page)=>/(^home$|homepage)/i.test(`${page.pageType} ${page.title}`)},
  {id:"locations",label:"Locations",match:(page:Page)=>/(location|local)/i.test(`${page.pageType} ${page.searchIntent}`)},
  {id:"company",label:"Company",match:(page:Page)=>/(about|team|trust|case|portfolio)/i.test(`${page.pageType} ${page.title}`)},
  {id:"legal",label:"Legal",match:(page:Page)=>/(legal|privacy|terms|cookie)/i.test(`${page.pageType} ${page.title}`)},
  {id:"contact",label:"Contact",match:(page:Page)=>/(contact|conversion)/i.test(`${page.pageType} ${page.title}`)},
  {id:"resources",label:"Resources",match:(page:Page)=>/(resource|blog|article|guide|support|faq)/i.test(`${page.pageType} ${page.title}`)},
  {id:"services",label:"Services",match:(page:Page)=>/(service|product|hub|pillar)/i.test(page.pageType)&&!/(location|local)/i.test(page.pageType)},
 ];
 const assigned=new Set<string>(),items:MenuItem[]=[];
 for(const group of groups){const matches=pages.filter(page=>!assigned.has(page.id)&&group.match(page));if(!matches.length)continue;const parentId=`custom-footer-${group.id}`;items.push({pageId:parentId,label:group.label,slug:"",parentPageId:null,custom:true});for(const page of matches){assigned.add(page.id);items.push({pageId:page.id,label:page.title,slug:page.slug,parentPageId:parentId})}}
 const remaining=pages.filter(page=>!assigned.has(page.id));if(remaining.length){const parentId="custom-footer-more";items.push({pageId:parentId,label:"More",slug:"",parentPageId:null,custom:true});items.push(...remaining.map(page=>({pageId:page.id,label:page.title,slug:page.slug,parentPageId:parentId})))}
 return items;
}
function footerMenuIncludingAllPages(saved:Record<string,unknown>[],pages:Page[]):MenuItem[]{
 const suggested=suggestedFooterMenuItems(pages);
 if(!saved.length)return suggested;
 const items:MenuItem[]=saved.map(item=>({pageId:String(item.pageId??""),label:string(item.label,"Menu item"),slug:String(item.slug??""),parentPageId:item.parentPageId?String(item.parentPageId):null,custom:item.custom===true})).filter(item=>item.pageId);
 const included=new Set(items.map(item=>item.pageId));
 const pageIds=new Set(pages.map(page=>page.id));
 for(const suggestion of suggested){
  if(!pageIds.has(suggestion.pageId)||included.has(suggestion.pageId))continue;
  if(suggestion.parentPageId&&!included.has(suggestion.parentPageId)){
   const parent=suggested.find(item=>item.pageId===suggestion.parentPageId);
   if(parent){items.push(parent);included.add(parent.pageId)}
  }
  items.push(suggestion);included.add(suggestion.pageId);
 }
 const canonicalParentByLabel=new Map<string,string>(),duplicateParentIds=new Map<string,string>();
 for(const item of items.filter(item=>item.custom&&!item.parentPageId)){
  const key=item.label.trim().toLowerCase(),canonicalId=canonicalParentByLabel.get(key);
  if(canonicalId)duplicateParentIds.set(item.pageId,canonicalId);else canonicalParentByLabel.set(key,item.pageId);
 }
 const normalizedItems=items.filter(item=>!duplicateParentIds.has(item.pageId)).map(item=>item.parentPageId&&duplicateParentIds.has(item.parentPageId)?{...item,parentPageId:duplicateParentIds.get(item.parentPageId)!}:item);
 const duplicateLabels=new Map<string,number>();
 for(const item of normalizedItems.filter(item=>!item.custom))duplicateLabels.set(item.label.trim().toLowerCase(),(duplicateLabels.get(item.label.trim().toLowerCase())??0)+1);
 return normalizedItems.map(item=>{
  if(item.custom||(duplicateLabels.get(item.label.trim().toLowerCase())??0)<2)return item;
  const page=pages.find(candidate=>candidate.id===item.pageId);
  if(!page)return item;
  return {...item,label:page.title.trim().toLowerCase()===item.label.trim().toLowerCase()?`${page.title} · /${page.slug}`:page.title};
 });
}

