  {!automaticWebsiteBuild&&<div className="sticky bottom-3 z-30 flex items-center justify-between gap-3 rounded-2xl border border-slate-200 bg-white/95 p-3 shadow-xl backdrop-blur"><button type="button" disabled={currentFlowIndex===0} onClick={()=>setStep(flow[Math.max(0,currentFlowIndex-1)][0])} className="rounded-lg border border-slate-300 bg-white px-4 py-2.5 text-sm font-bold text-slate-700 disabled:opacity-40">← Back</button><div className="hidden text-center sm:block"><div className="text-[10px] font-black uppercase tracking-wide text-slate-400">Website Builder</div><div className="text-xs font-bold text-slate-700">Step {currentFlowIndex+1} of {flow.length} · {flow[currentFlowIndex][1]}</div></div>{currentFlowIndex<flow.length-1?<button type="button" disabled={!done(step)} onClick={()=>setStep(flow[currentFlowIndex+1][0])} className="rounded-lg bg-brand-700 px-5 py-2.5 text-sm font-black text-white shadow-md disabled:cursor-not-allowed disabled:bg-slate-300 disabled:shadow-none">{done(step)?`Continue to ${flow[currentFlowIndex+1][1]} →`:"Complete this step to continue"}</button>:<span className={`rounded-lg px-5 py-2.5 text-sm font-black ${done(step)?"bg-emerald-600 text-white":"bg-amber-100 text-amber-800"}`}>{done(step)?"✓ Website workflow complete":"Complete publishing to finish"}</span>}</div>}
  {authorityDecisionOpen&&<div className="fixed inset-0 z-[140] grid place-items-center bg-slate-950/65 p-4" role="dialog" aria-modal="true" aria-label="Skip Local Authority pages for now"><button type="button" className="absolute inset-0" aria-label="Close dialog" onClick={()=>busy!=="authority-defer"&&setAuthorityDecisionOpen(false)}/><div className="relative w-full max-w-xl overflow-hidden rounded-2xl bg-white shadow-2xl"><div className="border-b bg-gradient-to-r from-violet-50 via-white to-cyan-50 px-6 py-5"><div className="text-xs font-black uppercase tracking-wide text-violet-700">Local Authority stage</div><h2 className="mt-1 text-xl font-black text-slate-950">Skip these pages for now?</h2><p className="mt-2 text-sm leading-6 text-slate-600">You can continue with the core website and launch it without these {activeAuthorityPages.length} location and service-location page{activeAuthorityPages.length===1?"":"s"}. Nothing is removed from the approved SEO plan.</p></div><div className="space-y-4 p-6"><div className="rounded-xl border border-emerald-200 bg-emerald-50 p-4"><b className="text-sm text-emerald-900">You can skip now, create the content after the website launches, and publish it later.</b><p className="mt-1 text-xs leading-5 text-emerald-800">After launch, return to Site Architect and choose <b>Create these pages now</b>. SENuke AI will generate the content and images, run review and approval, then publish the pages as a new website update.</p></div><div className="grid gap-2 sm:grid-cols-2"><div className="rounded-xl border border-slate-200 p-3"><b className="text-xs text-slate-900">Preserved for later</b><p className="mt-1 text-xs leading-5 text-slate-500">Approved keywords, intent clusters, target URLs, briefs, and Local SEO mapping.</p></div><div className="rounded-xl border border-violet-200 bg-violet-50/50 p-3"><b className="text-xs text-violet-900">Not included in this launch</b><p className="mt-1 text-xs leading-5 text-violet-700">Content, images, navigation, quality checks, approval, and publishing for these authority pages.</p></div></div><label className="block text-xs font-black text-slate-700">Optional note<textarea rows={3} value={authorityReason} onChange={event=>setAuthorityReason(event.target.value)} placeholder="Example: Launch the core website first and add city authority pages in phase two." className="mt-1.5 w-full rounded-xl border border-slate-300 p-3 text-sm font-normal leading-6"/></label></div><div className="flex flex-wrap items-center justify-between gap-3 border-t bg-slate-50 px-6 py-4"><button type="button" disabled={busy==="authority-defer"} onClick={()=>setAuthorityDecisionOpen(false)} className="rounded-lg border bg-white px-4 py-2.5 text-sm font-bold text-slate-700">Keep in this launch</button><button type="button" disabled={busy==="authority-defer"} onClick={()=>void updateAuthorityLifecycle("defer")} className="rounded-lg bg-violet-700 px-5 py-2.5 text-sm font-black text-white disabled:bg-slate-300">{busy==="authority-defer"?"Scheduling…":"Skip Now · Create After Launch"}</button></div></div></div>}
  {localEvidenceModal&&<div className="fixed inset-0 z-[130] grid place-items-center bg-slate-950/65 p-4" role="dialog" aria-modal="true" aria-label="Add verified local evidence"><button type="button" className="absolute inset-0" aria-label="Close local evidence dialog" onClick={()=>!busy.startsWith("local-evidence-")&&setLocalEvidenceModal(null)}/><div className="relative flex max-h-[92vh] w-full max-w-2xl flex-col overflow-hidden rounded-2xl bg-white shadow-2xl"><div className="border-b bg-gradient-to-r from-indigo-50 to-white px-6 py-5"><div className="text-xs font-black uppercase tracking-wide text-indigo-700">Resolve local-page quality blocker</div><h2 className="mt-1 text-xl font-black text-slate-950">Verify local evidence for {localEvidenceModal.pageTitle}</h2><p className="mt-1 text-sm leading-6 text-slate-500">This page targets <b>{localEvidenceModal.location}</b>. Confirm that the business genuinely provides this service there, then add one useful location-specific fact. SENuke AI will not invent this evidence.</p></div><div className="flex-1 space-y-4 overflow-y-auto p-6"><label className={`block cursor-pointer rounded-xl border p-4 ${localEvidenceModal.confirmed?"border-emerald-300 bg-emerald-50":"border-slate-200"}`}><input type="checkbox" checked={localEvidenceModal.confirmed} onChange={event=>{setLocalEvidenceModal({...localEvidenceModal,confirmed:event.target.checked});if(localEvidenceError)setLocalEvidenceError("")}} className="mr-2"/><b className="text-sm text-slate-900">I confirm this service is genuinely available in {localEvidenceModal.location}</b><p className="mt-1 pl-5 text-xs leading-5 text-slate-500">Do not confirm an office, licence, service area, or delivery capability that the business cannot support.</p></label><label className="block text-xs font-black text-slate-700">What makes this page useful and specific to {localEvidenceModal.location}?<textarea rows={7} value={localEvidenceModal.evidence} onChange={event=>{setLocalEvidenceModal({...localEvidenceModal,evidence:event.target.value});if(localEvidenceError)setLocalEvidenceError("")}} className="mt-2 w-full rounded-xl border border-slate-300 p-3 text-sm leading-6" placeholder="Example: We provide remote consultations to Toronto customers, use a location-specific onboarding process, and can document service availability through approved business records. Do not enter private client information."/><span className={`mt-1 block text-right text-[10px] font-bold ${localEvidenceModal.evidence.trim().length>=20?"text-emerald-600":"text-slate-400"}`}>{localEvidenceModal.evidence.trim().length} characters · 20 minimum</span></label>{localEvidenceError&&<div role="alert" className="rounded-xl border border-rose-200 bg-rose-50 p-3 text-sm font-semibold leading-6 text-rose-800">{localEvidenceError}</div>}<div className="rounded-xl border border-amber-200 bg-amber-50 p-4"><b className="text-sm text-amber-900">Use verifiable information only</b><p className="mt-1 text-xs leading-5 text-amber-800">Suitable evidence includes genuine service availability, an approved local case study, local delivery details, a verified office or service area, applicable regulations, or an approved testimonial. If none exists, this local page should be reconsidered in the SEO Page Map.</p></div></div><div className="flex flex-wrap items-center justify-between gap-3 border-t bg-slate-50 px-6 py-4"><button type="button" disabled={busy.startsWith("local-evidence-")} onClick={()=>setLocalEvidenceModal(null)} className="rounded-lg border bg-white px-4 py-2 text-sm font-bold">Cancel</button><button type="button" disabled={busy===`local-evidence-${localEvidenceModal.pageId}`} onClick={()=>void saveLocalEvidence()} className="rounded-lg bg-indigo-700 px-5 py-2.5 text-sm font-black text-white disabled:bg-slate-300">{busy===`local-evidence-${localEvidenceModal.pageId}`?"Saving evidence…":"Save Evidence & Resolve"}</button></div></div></div>}
