 return <Panel title={title}><div className="flex flex-wrap items-start justify-between gap-3"><div className="min-w-0 flex-1"><p className="text-sm leading-6 text-slate-500">{description}</p><p className="mt-1 text-xs font-semibold text-slate-400">Works with mouse and touch. Use a blank link for a heading or dropdown-only label.</p></div><Action inline busy={busy} disabled={!items.length} onClick={()=>onSave(items,showAllPages?excludedPageIds:undefined)}>{saveLabel}</Action></div>
  <div className="mt-4 grid gap-2 rounded-xl border border-slate-200 bg-slate-50 p-4 sm:grid-cols-[1fr_1fr_auto]"><label className="text-xs font-bold text-slate-700">{showAllPages?"New footer column":"Menu label"}<input value={customLabel} onChange={event=>setCustomLabel(event.target.value)} className="mt-1 w-full rounded-lg border bg-white p-2 text-sm" placeholder="Services"/></label><label className="text-xs font-bold text-slate-700">{showAllPages?"Column link (usually blank)":"Link (optional)"}<input value={customUrl} onChange={event=>setCustomUrl(event.target.value)} className="mt-1 w-full rounded-lg border bg-white p-2 text-sm" placeholder={showAllPages?"Leave blank for a footer heading":"/services or blank for dropdown only"}/></label><button type="button" disabled={!customLabel.trim()} onClick={addCustom} className="self-end rounded-lg border border-brand-200 bg-white px-4 py-2 text-sm font-black text-brand-700 disabled:text-slate-300">{showAllPages?"Add Footer Column":"Add Menu Item"}</button></div>
  {showAllPages?<div className="mt-4 rounded-xl border border-slate-200 bg-white p-4"><b className="text-xs uppercase tracking-wide text-slate-500">Footer columns</b><div className="mt-3 flex flex-wrap gap-2">{footerColumns.map(column=><div key={column.pageId} className="flex items-center gap-2 rounded-lg border border-slate-200 bg-slate-50 p-2"><input aria-label="Footer column name" value={column.label} onChange={event=>setItems(current=>current.map(item=>item.pageId===column.pageId?{...item,label:event.target.value}:item))} className="w-36 bg-transparent px-1 text-xs font-black outline-none"/><button type="button" onClick={()=>removeItem(column.pageId)} className="rounded border border-rose-200 bg-white px-2 py-1 text-[10px] font-black text-rose-700">Remove</button></div>)}{!footerColumns.length&&<span className="text-xs font-semibold text-slate-400">No columns yet. Pages will appear under Quick links until you add one.</span>}</div></div>:<div className="mt-4 min-h-28 overflow-hidden rounded-xl border border-slate-200 bg-slate-50/70 p-3"><DndProvider backend={MultiBackend} options={getBackendOptions()}><Tree<MenuItem> tree={tree} rootId={rootId} onDrop={applyTree} sort={false} insertDroppableFirst={false} initialOpen={true} dropTargetOffset={10} classes={{root:"space-y-1",container:"space-y-1",listItem:"list-none",dropTarget:"rounded-xl bg-brand-50",draggingSource:"opacity-30",placeholder:"relative h-1 rounded bg-brand-500"}} placeholderRender={(_node,{depth})=><div className="h-1 rounded bg-brand-500" style={{marginLeft:depth*24}}/>} dragPreviewRender={({item})=><div className="rounded-lg border border-brand-300 bg-white px-4 py-3 text-sm font-black shadow-xl">{item.text}</div>} render={(node,{depth,isOpen,onToggle,hasChild,handleRef,containerRef,isDragging,isDropTarget})=>{const item=node.data!;return <div ref={containerRef} style={{marginLeft:depth*24}} className={`my-1 flex items-center gap-2 rounded-xl border bg-white p-3 shadow-sm transition ${isDragging?"opacity-30":""} ${isDropTarget?"border-brand-500 ring-2 ring-brand-100":"border-slate-200"}`}><div ref={handleRef} className="cursor-grab select-none rounded-md bg-slate-100 px-2 py-1 text-lg leading-none text-slate-500 active:cursor-grabbing" title="Drag to move">⋮⋮</div>{hasChild?<button type="button" onClick={onToggle} className="grid h-7 w-7 place-items-center rounded-md border text-xs font-black text-slate-600">{isOpen?"−":"+"}</button>:<span className="h-7 w-7"/>}<div className="min-w-0 flex-1"><b className="block truncate text-sm text-slate-900">{node.text}</b><p className="truncate text-xs text-brand-700">{item.slug||(item.custom?"Dropdown only · no destination":"/")}</p></div><span className="rounded-full bg-slate-100 px-2 py-1 text-[9px] font-black uppercase text-slate-500">{depth?`level ${depth+1}`:item.custom?"custom":"page"}</span><button type="button" onClick={()=>removeItem(String(node.id))} className="rounded-md border border-rose-200 px-2 py-1 text-[10px] font-black text-rose-700">Remove</button></div>}}/></DndProvider>{!items.length&&<p className="p-6 text-center text-sm text-slate-500">Add a page or custom item to begin the menu.</p>}</div>}
  <div className="mt-5 rounded-xl border border-slate-200 bg-slate-50 p-4"><div className="flex items-center justify-between gap-3"><b className="text-xs uppercase tracking-wide text-slate-500">{showAllPages?"Choose footer pages":"Website pages not yet in this menu"}</b><span className="rounded-full bg-white px-2 py-1 text-[10px] font-black text-slate-600">{showAllPages?`${pages.length-excludedPageIds.length} included`: `${available.length} of ${pages.length}`}</span></div>{showAllPages?<div className="mt-3 max-h-[30rem] space-y-2 overflow-y-auto pr-1">{pages.map(page=>{const item=items.find(candidate=>candidate.pageId===page.id),included=Boolean(item);return <div key={page.id} className={`grid gap-2 rounded-xl border p-3 md:grid-cols-[minmax(0,1fr)_minmax(150px,0.7fr)_minmax(140px,0.55fr)_auto] ${included?"border-slate-200 bg-white":"border-dashed border-slate-300 bg-slate-100/60"}`}><div className="min-w-0"><b className="block truncate text-xs text-slate-800">{page.title}</b><span className="mt-1 block truncate text-[10px] font-medium text-slate-400">/{page.slug}</span></div>{included?<><input aria-label={`Footer label for ${page.title}`} value={item?.label??page.title} onChange={event=>updatePageItem(page,{label:event.target.value})} className="rounded-lg border border-slate-300 bg-white px-2.5 py-2 text-xs font-semibold"/><select aria-label={`Footer column for ${page.title}`} value={item?.parentPageId??""} onChange={event=>updatePageItem(page,{parentPageId:event.target.value||null})} className="rounded-lg border border-slate-300 bg-white px-2.5 py-2 text-xs font-semibold"><option value="">Quick links</option>{footerColumns.map(column=><option key={column.pageId} value={column.pageId}>{column.label}</option>)}</select><button type="button" onClick={()=>toggleFooterPage(page,false)} className="rounded-lg border border-rose-200 bg-white px-3 py-2 text-xs font-black text-rose-700">Remove</button></>:<><span className="md:col-span-2 self-center text-xs font-semibold text-slate-400">Not shown in the website footer</span><button type="button" onClick={()=>toggleFooterPage(page,true)} className="rounded-lg bg-emerald-600 px-3 py-2 text-xs font-black text-white">Add</button></>}</div>})}</div>:available.length?<div className="mt-3 grid gap-2 sm:grid-cols-2">{available.map(page=><button key={page.id} type="button" onClick={()=>setItems(current=>[...current,{pageId:page.id,label:page.title,slug:page.slug,parentPageId:null}])} className="rounded-lg border border-slate-300 bg-white px-3 py-2 text-left text-xs font-bold text-slate-700"><span className="block">+ {page.title}</span><span className="mt-1 block truncate font-medium text-slate-400">/{page.slug}</span></button>)}</div>:<p className="mt-3 text-sm font-semibold text-emerald-700">Every Site Architect content page is included in the menu.</p>}</div>
 </Panel>
